   214	/****************************************************************************
   215	 * Name: esp_ipc_init
   216	 *
   217	 * Description:
   218	 *   Initialize inter-processor call module. This function creates IPC tasks
   219	 *   on each CPU. These tasks are started with high priority and are normally
   220	 *   inactive, waiting until one of the esp_ipc_call_* functions is used.
   221	 *
   222	 ****************************************************************************/
   223	
   224	/* Note: We don't use __attribute__((constructor)) because the NuttX scheduler
   225	 * is not ready when constructors run. Instead, we use lazy initialization in
   226	 * esp_ipc_ensure_init() called by all public IPC functions.
   227	 */
   228	
   229	static void esp_ipc_init(void)
   230	{
   231	  int cpu;
   232	  int ret;
   233	
   234	  if (__atomic_load_n(&s_ipc_initialized, __ATOMIC_ACQUIRE))
   235	    {
   236	      return;
   237	    }
   238	
   239	  /* Ensure the scheduler is ready */
   240	
   241	  if (!OSINIT_OS_READY())
   242	    {
   243	      return;
   244	    }
   245	
   246	  ret = nxmutex_lock(&s_ipc_init_mutex);
   247	  if (ret < 0)
   248	    {
   249	      return;
   250	    }
   251	
   252	  /* Other CPUs can enter here concurrently; a scheduler lock is not enough. */
   253	
   254	  if (s_ipc_initialized || s_ipc_init_error)
   255	    {
   256	      nxmutex_unlock(&s_ipc_init_mutex);
   257	      return;
   258	    }
   259	
   260	  /* Initialize synchronization primitives and create tasks for each CPU */
   261	
   262	  for (cpu = 0; cpu < CONFIG_SMP_NCPUS; cpu++)
   263	    {
   264	      nxmutex_init(&s_ipc_mutex[cpu]);
   265	      nxsem_init(&s_ipc_ack[cpu], 0, 0);
   266	      nxsem_init(&s_ipc_notify[cpu], 0, 0);
   267	
   268	      ret = esp_ipc_init_task(cpu);
   269	      if (ret < 0)
   270	        {
   271	          s_ipc_init_error = ret;
   272	          nxmutex_unlock(&s_ipc_init_mutex);
   273	          return;
   274	        }
   275	    }
   276	
   277	  __atomic_store_n(&s_ipc_initialized, true, __ATOMIC_RELEASE);
   278	
   279	  nxmutex_unlock(&s_ipc_init_mutex);
   280	
   281	  sinfo("IPC tasks created successfully\n");
   282	}
