   284	/****************************************************************************
   285	 * Name: esp_ipc_ensure_init
   286	 *
   287	 * Description:
   288	 *   Ensure IPC is initialized. Called lazily if constructor didn't run
   289	 *   when scheduler was ready.
   290	 *
   291	 ****************************************************************************/
   292	
   293	static bool esp_ipc_ensure_init(void)
   294	{
   295	  if (__atomic_load_n(&s_ipc_initialized, __ATOMIC_ACQUIRE))
   296	    {
   297	      return true;
   298	    }
   299	
   300	  if (OSINIT_OS_READY() && !up_interrupt_context())
   301	    {
   302	      esp_ipc_init();
   303	    }
   304	
   305	  return __atomic_load_n(&s_ipc_initialized, __ATOMIC_ACQUIRE);
   306	}
