   308	/****************************************************************************
   309	 * Name: esp_ipc_call_and_wait
   310	 *
   311	 * Description:
   312	 *   Execute a function on another CPU and wait.
   313	 *
   314	 ****************************************************************************/
   315	
   316	static esp_err_t esp_ipc_call_and_wait(uint32_t cpu_id, esp_ipc_func_t func,
   317	                                       void *arg, esp_ipc_wait_t wait_for)
   318	{
   319	  FAR struct tcb_s *current_task;
   320	  int ret;
   321	
   322	  if (func == NULL || cpu_id >= CONFIG_SMP_NCPUS)
   323	    {
   324	      return ESP_ERR_INVALID_ARG;
   325	    }
   326	
   327	  if (up_interrupt_context())
   328	    {
   329	      return ESP_ERR_INVALID_STATE;
   330	    }
   331	
   332	  if (!esp_ipc_ensure_init())
   333	    {
   334	      return ESP_ERR_INVALID_STATE;
   335	    }
   336	
   337	  if (cpu_id >= CONFIG_SMP_NCPUS)
   338	    {
   339	      return ESP_ERR_INVALID_ARG;
   340	    }
   341	
   342	  if (s_ipc_task_handle[cpu_id] == NULL)
   343	    {
   344	      return ESP_ERR_INVALID_STATE;
   345	    }
   346	
   347	  if (!OSINIT_OS_READY())
   348	    {
   349	      return ESP_ERR_INVALID_STATE;
   350	    }
   351	
   352	  current_task = this_task();
   353	
   354	  /* Check for recursion: if we're already the IPC task, run directly */
   355	
   356	  if (current_task == s_ipc_task_handle[cpu_id])
   357	    {
   358	      func(arg);
   359	      return ESP_OK;
   360	    }
   361	
   362	  /* Take mutex to serialize IPC calls */
   363	
   364	  ret = nxmutex_lock(&s_ipc_mutex[cpu_id]);
   365	  if (ret < 0)
   366	    {
   367	      return ESP_FAIL;
   368	    }
   369	
   370	  s_func_arg[cpu_id] = arg;
   371	  s_wait_for[cpu_id] = wait_for;
   372	
   373	  /* s_func must be set after all other parameters.
   374	   * The ipc_task uses this as indicator of the IPC being prepared.
   375	   */
   376	
   377	  s_func[cpu_id] = func;
   378	
   379	  /* Notify the IPC task */
   380	
   381	  nxsem_post(&s_ipc_notify[cpu_id]);
   382	
   383	  /* Wait for acknowledgement */
   384	
   385	  nxsem_wait_uninterruptible(&s_ipc_ack[cpu_id]);
   386	
   387	  nxmutex_unlock(&s_ipc_mutex[cpu_id]);
   388	
   389	  return ESP_OK;
   390	}
