                                       int planeno,
                                       FAR struct fb_planeinfo_s *pinfo)
{
  FAR struct esp32p4_dsi_fb_s *fb =
    (FAR struct esp32p4_dsi_fb_s *)vtable;

  if (fb == NULL || pinfo == NULL || planeno != 0)
    {
