+  if (ret != 0)
+    {
+      sem_destroy(&probe.start);
+      free(buffer);
+      return EXIT_FAILURE;
+    }
+
+  printf("smp_psram: buffer=%p bytes=%zu rounds=%lu\n", buffer, bytes, loops);
+  for (cpu = 0; cpu < 2; cpu++)
