    defined(CONFIG_ESP32S3_SPIRAM_BULK_POOL_SIZE) && \
    CONFIG_ESP32S3_SPIRAM_BULK_POOL_SIZE > 0
    else if (esp32s3_ptr_is_extram(pointer)) {
        region = "PSRAM";
    } else {
        region = "SRAM";
    }
#else
    else {
        region = "unknown";
    }
#endif

    printf("[smart_home_mem] %s ptr=%p region=%s\n",
           label ? label : "pointer", pointer, region);
