static void snapshot(const uint16_t *fb, const char *var)
{
    const char *path = getenv(var);
    FILE *out;

    if (!path) return;
    out = fopen(path, "wb");
    if (!out) return;
    fprintf(out, "P6\n1024 600\n255\n");
    for (int i = 0; i < 1024 * 600; i++) {
        uint16_t v = fb[i];
        uint8_t rgb[3];

