    }

    for (i = 0u; i < smart_home_llm_backend_count(); i++) {
        const smart_home_llm_backend_preset_t *preset = &g_llm_presets[i];
        if ((preset->flags & SMART_HOME_LLM_FLAG_CUSTOM) != 0u) {
            continue;
