/* 确保配置目录存在（首次运行可能不存在） */
static int ensure_config_dir(const char *path)
{
    char dir[SMART_HOME_CONFIG_PATH_MAX];
    const char *slash;
    size_t len;

    if (!path) {
        return -1;
    }

    slash = strrchr(path, '/');
    if (!slash || slash == path) {
        return 0;
    }

    len = (size_t)(slash - path);
    if (len >= sizeof(dir)) {
        return -1;
    }
    memcpy(dir, path, len);
    dir[len] = '\0';

    if (mkdir(dir, 0700) == 0) {
        return 0;
    }
    return (errno == EEXIST) ? 0 : -1;
}

