static bool type_is_dangerous(const char *type_name)
{
    size_t i;

    if (!type_name)
      {
        return false;
      }

    for (i = 0; i < sizeof(g_miloco_dangerous_types) /
                    sizeof(g_miloco_dangerous_types[0]); i++)
