        ok = service->reachable || service->config_dirty ||
             service->client_config.host[0] != '\0';
        unlock_state((smart_home_miloco_t *)service);
    }
    return ok;
}

bool smart_home_miloco_bound(const smart_home_miloco_t *service)
{
