/* 有界 JSON 转义拷贝（含 " 与 \ 及控制字符），返回写入长度；
 * 溢出时截断到 cap-1。 */
static size_t json_escape_bounded(char *dst, size_t cap, const char *src)
{
    size_t used = 0;

    while (*src && used + 1 < cap) {
        char c = *src++;

        if (c == '"' || c == '\\') {
            if (used + 2 >= cap) {
                break;
            }
            dst[used++] = '\\';
            dst[used++] = c;
        } else if ((unsigned char)c >= 0x20u) {
            dst[used++] = c;
        } else {
            dst[used++] = ' ';
        }
    }
    dst[used] = '\0';
    return used;
}

