static void build_tools_panel(smart_home_lvgl_t *ui, lv_obj_t *panel)
{
    size_t count = ui && ui->app ? ui->app->local_tool_access_count : 0;
    int y = 56;

    panel_title(panel, "工具权限");
    if (!ui || !ui->app) {
