    ret = append_json(buffer, buffer_size, &offset,
                      "{\"revision\":%lu,\"devices\":[",
                      (unsigned long)service->revision);
    if (ret != AGENT_OK) {
        return ret;
    }

    for (i = 0; i < SMART_HOME_MAX_DEVICES; i++) {
        if (!service->state->devices[i].used) {
            continue;
