static int check_version(const cJSON *root, char *error, size_t error_size)
{
    const cJSON *version;

    if (!root || !cJSON_IsObject(root)) {
        set_error(error, error_size, "config is not a JSON object");
        return AGENT_ERROR_PARSE;
