/* 读取文件到堆缓冲。返回 0 成功；-1 文件缺失；1 读取/IO/过大错误。 */
static int read_file(const char *path,
                     char **out_text,
                     size_t *out_size,
                     char *error,
                     size_t error_size)
{
    FILE *file;
    long size;
    char *text;

    file = fopen(path, "rb");
    if (!file) {
        if (errno == ENOENT) {
            return -1; /* 缺失 */
        }
        set_error(error, error_size, "cannot open config file");
        return 1; /* 权限/IO 错误 */
    }

    if (fseek(file, 0, SEEK_END) != 0) {
        fclose(file);
        set_error(error, error_size, "seek failed");
        return 1;
    }
    size = ftell(file);
    if (size < 0) {
        fclose(file);
        set_error(error, error_size, "tell failed");
        return 1;
    }
    if (size > (long)CONFIG_STORE_MAX_FILE_SIZE) {
        fclose(file);
        set_error(error, error_size, "file too large");
        return 1;
    }
    if (fseek(file, 0, SEEK_SET) != 0) {
        fclose(file);
        set_error(error, error_size, "seek failed");
        return 1;
    }

    text = malloc((size_t)size + 1u);
    if (!text) {
        fclose(file);
        set_error(error, error_size, "out of memory");
        return 1;
    }
    if (fread(text, 1u, (size_t)size, file) != (size_t)size) {
        fclose(file);
        free(text);
        set_error(error, error_size, "read failed");
        return 1;
    }
    text[size] = '\0';
    fclose(file);

    *out_text = text;
    *out_size = (size_t)size;
    return 0;
}

