#define MEMORY_FILE_BYTES 16384u

typedef struct {
    char key[SMART_HOME_USER_MEMORY_KEY_BYTES + 1u];
    char value[SMART_HOME_USER_MEMORY_VALUE_BYTES + 1u];
    char evidence[SMART_HOME_USER_MEMORY_EVIDENCE_BYTES + 1u];
} preference_t;

