+    if (!count && offset < memory->count) { ret = AGENT_ERROR_CAPACITY; goto done; }
+    text = cJSON_PrintUnformatted(root);
+    if (!text) goto done;
+    if (strlen(text) > max_bytes) { ret = AGENT_ERROR_CAPACITY; goto done; }
